import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

import {
  add,
  compare,
  fromNumber,
  mul,
  parseDecimal,
  roundHalfAwayFromZero,
  sub,
  sum,
  toFixedText,
  toNumber,
  toText,
} from "../decimal.js";
import { lineNetAmount, moneyText, vatAmount, money } from "../monetary.js";

/**
 * Tests exact decimal calculations using independently generated results.
 *
 * Why:
 * JavaScript floating-point arithmetic can introduce rounding errors.
 * For example, 30 × 0.0055 should round to 0.17, not 0.16.
 *
 * The expected results are generated by rounding-vectors.py using
 * Python's decimal module, which is independent of our TypeScript engine.
 *
 * The JSON includes:
 * - Fixed rounding, invoice line, and VAT examples
 * - 2,000 randomly generated invoice line calculations
 * - 2,000 randomly generated VAT calculations
 *
 * Tests read the saved JSON directly. Python is only needed if
 * someone wants to regenerate the reference data.
 */
interface Vectors {
  round: { value: string; places: number; expected: string }[];
  line: {
    quantity: string;
    unitPrice: string;
    charges: string[];
    allowances: string[];
    expected: string;
  }[];
  vat: { taxable: string; rate: string; expected: string }[];
  /** [quantity, unitPrice, expected] */
  randomLine: [string, string, string][];
  /** [taxable, rate, expected] */
  randomVat: [string, string, string][];
}
const vectors = JSON.parse(
  readFileSync(new URL("./rounding-vectors.json", import.meta.url), "utf8"),
) as Vectors;

/**
 * Converts test charges and discounts into the format expected
 * by lineNetAmount().
 *
 * Example:
 * charges = ["2.00"]
 * allowances = ["1.00"]
 *
 * Result:
 * [
 *   { amount: 2, isCharge: true },
 *   { amount: 1, isCharge: false }
 * ]
 *
 * A charge increases the invoice amount.
 * An allowance (discount) decreases it.
 */
const adjustments = (
  charges: string[],
  allowances: string[],
): { amount: number; isCharge: boolean }[] => [
  ...charges.map((c) => ({ amount: Number(c), isCharge: true })),
  ...allowances.map((a) => ({ amount: Number(a), isCharge: false })),
];

/**
 * Checks how decimal values are read from strings and JavaScript numbers.
 *
 * parseDecimal() reads decimal text directly.
 * fromNumber() converts a JavaScript number into decimal text first.
 */
describe("parseDecimal / fromNumber", () => {
  // Valid inputs should preserve their exact decimal meaning.
  // For example, ".5" becomes "0.5" and "1.5e3" becomes "1500".
  it.each([
    ["0.0055", "0.0055"],
    ["-12", "-12"],
    ["+7.50", "7.50"],
    [".5", "0.5"],
    ["1e-7", "0.0000001"],
    ["1.5e3", "1500"],
    ["-2.5E-2", "-0.025"],
    ["1e+21", "1000000000000000000000"],
    ["0", "0"],
    ["-0", "0"],
    ["000123.4500", "123.4500"],
  ])("parses %s exactly", (input, text) => {
    expect(toText(parseDecimal(input))).toBe(text);
  });

  it.each([
    "",
    " 1",
    "1 ",
    "1,5",
    "abc",
    "1.2.3",
    "NaN",
    "Infinity",
    "--1",
    "1e",
    "e5",
    "1e1001",
    "1e-1001",
    "0x10",
  ])("refuses %j", (input) => {
    expect(() => parseDecimal(input)).toThrow();
  });

  /**
   * Checks that fromNumber() uses the number's decimal text.
   *
   * Example:
   * fromNumber(0.0055) → "0.0055"
   *
   * Important:
   * JavaScript has already calculated 0.1 + 0.2 as
   * 0.30000000000000004.
   *
   * fromNumber() cannot undo an earlier calculation error.
   */
  it("reads numbers through their shortest round-trip text, not their binary value", () => {
    expect(toText(fromNumber(0.0055))).toBe("0.0055");
    expect(toText(fromNumber(0.1 + 0.2))).toBe("0.30000000000000004");
    expect(toText(fromNumber(1e-7))).toBe("0.0000001");
    expect(toText(fromNumber(1e21))).toBe("1000000000000000000000");
    expect(toText(fromNumber(-0))).toBe("0");
  });

  it("refuses NaN and infinities", () => {
    expect(() => fromNumber(Number.NaN)).toThrow();
    expect(() => fromNumber(Number.POSITIVE_INFINITY)).toThrow();
    expect(() => fromNumber(Number.NEGATIVE_INFINITY)).toThrow();
  });

  /**
   * Checks very large and very small JavaScript numbers.
   *
   * MAX_VALUE is approximately 1.8 × 10^308.
   * MIN_VALUE is approximately 5 × 10^-324.
   *
   * BigInt can handle the resulting large integers without
   * the fixed 64-bit integer limit.
   *
   * A tiny positive number rounds to 0.00 at two decimal places.
   */
  it("handles the extremes of a JavaScript number without overflow", () => {
    const max = fromNumber(Number.MAX_VALUE); // about 1.8e308: 309 digits as BigInt
    expect(toText(max).length).toBe(309);
    expect(compare(mul(max, max), max)).toBe(1); // BigInt never overflows
    expect(toText(fromNumber(Number.MIN_VALUE)).startsWith("0.000")).toBe(true); // 5e-324
    expect(toText(roundHalfAwayFromZero(fromNumber(Number.MIN_VALUE), 2))).toBe("0.00");
  });
});

/**
 * Checks exact arithmetic without ordinary JavaScript floating-point errors.
 *
 * Example:
 * JavaScript: 0.1 + 0.2 = 0.30000000000000004
 * Decimal:    0.1 + 0.2 = 0.3
 */
describe("exact arithmetic", () => {
  it("adds, subtracts, multiplies without binary error", () => {
    expect(toText(add(parseDecimal("0.1"), parseDecimal("0.2")))).toBe("0.3");
    expect(toText(sub(parseDecimal("1"), parseDecimal("0.9")))).toBe("0.1");
    expect(toText(mul(parseDecimal("30"), parseDecimal("0.0055")))).toBe("0.1650");
    expect(toText(sum([parseDecimal("0.10"), parseDecimal("0.20"), parseDecimal("-0.05")]))).toBe(
      "0.25",
    );
  });

  it("compares across scales", () => {
    expect(compare(parseDecimal("1.50"), parseDecimal("1.5"))).toBe(0);
    expect(compare(parseDecimal("-0.01"), parseDecimal("0"))).toBe(-1);
  });

  it("converts back to numbers exactly for 2-decimal money", () => {
    expect(toNumber(parseDecimal("6125.75"))).toBe(6125.75);
    expect(toNumber(parseDecimal("-0.17"))).toBe(-0.17);
  });
});

/**
 * Checks rounding against the Python reference values.
 *
 * Half away from zero means:
 *   0.165  →  0.17
 *  -0.165  → -0.17
 *
 * The rounding rule behaves symmetrically for positive
 * and negative values.
 */
describe("roundHalfAwayFromZero (reference vectors)", () => {
  it.each(vectors.round.map((c) => [c.value, c.places, c.expected] as const))(
    "%s to %i places = %s",
    (value, places, expected) => {
      expect(toFixedText(parseDecimal(value), places)).toBe(expected);
    },
  );

  it("is symmetric: round(-x) = -round(x)", () => {
    for (const v of ["0.005", "0.015", "0.165", "1.005", "2.675", "0.9949", "12.345"]) {
      const positive = toFixedText(parseDecimal(v), 2);
      expect(toFixedText(parseDecimal(`-${v}`), 2)).toBe(
        positive === "0.00" ? "0.00" : `-${positive}`,
      );
    }
  });

  it("never writes -0", () => {
    expect(toFixedText(parseDecimal("-0.001"), 2)).toBe("0.00");
  });
});

/**
 * Checks invoice line net amounts (BT-131).
 *
 * Calculation:
 * 1. Multiply quantity by unit price.
 * 2. Round that product to two decimal places.
 * 3. Add charges and subtract allowances.
 *
 * Example:
 * 3 × 1.005 = 3.015 → 3.02
 *
 * This follows the supported Peppol R120 calculation model.
 */
describe("lineNetAmount: Peppol BT-131 (reference vectors)", () => {
  it.each(
    vectors.line.map(
      (c) => [c.quantity, c.unitPrice, c.charges, c.allowances, c.expected] as const,
    ),
  )(
    "%s × %s, charges %j, allowances %j = %s",
    (quantity, unitPrice, charges, allowances, expected) => {
      expect(
        moneyText(
          lineNetAmount(Number(quantity), Number(unitPrice), adjustments(charges, allowances)),
        ),
      ).toBe(expected);
    },
  );

  /**
   * Rounding must happen before discounts.
   *
   * Step 1: 1 × 0.005 = 0.005
   * Step 2: Round 0.005 → 0.01
   * Step 3: Subtract discount 1.00
   *
   * Correct:   0.01 - 1.00 = -0.99
   * Incorrect: round(0.005 - 1.00) = -1.00
   */
  it("rounds quantity × price on its own, before adjustments (sign-stable when the sum crosses zero)", () => {
    expect(moneyText(lineNetAmount(1, 0.005, [{ amount: 1, isCharge: false }]))).toBe("-0.99");
  });

  /**
   * Tests 2,000 independently generated invoice line calculations.
   *
   * Each generated result is compared against the exact calculation
   * from Python's decimal module.
   *
   * If any result differs, the test fails.
   */
  it("matches the reference on 2000 seeded random lines", () => {
    expect(vectors.randomLine).toHaveLength(2000);
    const wrong = vectors.randomLine.filter(
      ([quantity, unitPrice, expected]) =>
        moneyText(lineNetAmount(Number(quantity), Number(unitPrice))) !== expected,
    );
    expect(wrong.slice(0, 5)).toEqual([]);
  });
});

/**
 * Checks VAT calculations (BT-117) against independent reference values.
 *
 * Example:
 * Taxable amount = 14.50
 * VAT rate = 7%
 *
 * 14.50 × 0.07 = 1.015
 * Round to two decimals → 1.02
 *
 * This helps prevent a one-cent VAT calculation error.
 */
describe("vatAmount: BT-117 per category (reference vectors)", () => {
  it.each(vectors.vat.map((c) => [c.taxable, c.rate, c.expected] as const))(
    "%s × %s percent = %s",
    (taxable, rate, expected) => {
      expect(moneyText(vatAmount(money(Number(taxable)), Number(rate)))).toBe(expected);
    },
  );

  it("matches the reference on 2000 seeded random VAT amounts", () => {
    expect(vectors.randomVat).toHaveLength(2000);
    const wrong = vectors.randomVat.filter(
      ([taxable, rate, expected]) =>
        moneyText(vatAmount(money(Number(taxable)), Number(rate))) !== expected,
    );
    expect(wrong.slice(0, 5)).toEqual([]);
  });
});
